"""
Client Runner
"""
from serve_everything.remote.transparent_execution_proxy import TransparentExecutionProxy, enable_transparent_execution, disable_transparent_execution

class Client:
    def __init__(self, host = "localhost", port = 9090, auto_setting = True):
        """  
        Initializes the client, with the connecting server's configuration.  

        Parameters:  
        host (str): The hostname or IP address of the server. Defaults to "localhost".  
        port (int): The port number the server will listen on. Defaults to 9090.  
        auto_setting (bool): Whether to enable automatic configuration settings. Defaults to True.  
        """  
        self.proxy = None
        self.host = host
        self.port = port
        self.enabled = False
        if auto_setting:
            self.setup()

    def setup(self, transfer_local_moudules: bool=True, modules_to_share: list=None, source_dict: dict=None, other_codes: list=None, skip_modules: list=None):
        """  
        Setup data sharing between the client and the server.  

        Parameters:  
        transfer_local_modules (bool): Determines whether local modules should be transferred. Defaults to True.  
        modules_to_share (list): A list of module names to be shared. Defaults to None.  
        source_dict (dict): A dictionary containing source configurations or mappings. Defaults to None.  
        other_codes (list): A list of additional code files or snippets to include. Defaults to None.  
        skip_modules (list): A list of module names to exclude from the setup process. Defaults to None.  
        """
        try:
            # Create the transparent proxy
            if skip_modules is None:
                skip_modules=[]
            skip_modules.append(self.__module__)
            self.proxy = TransparentExecutionProxy(host=self.host, port=self.port, transfer_local_modules=transfer_local_moudules, modules_to_share=modules_to_share, source_dict=source_dict, other_codes=other_codes, skip_modules=skip_modules)
            # Enable transparent execution
            if self.proxy.is_available:
                enable_transparent_execution(self.proxy)
                self.enabled = True
            return True
        except Exception as e:
            print("Could not setup:" + str(e))
            # Disable transparent execution (restore original functions)  
            disable_transparent_execution()
            return False

    def run(self, code):
        """
        Explictly run code via Client.
        Note: this is intended for simple code running. For as source code module(imported from a file), not need this 'run', just call functions of it directly.

        Param:
            code  - str, dict, or list of source code.
        """
        try:
            if self.enabled:
                self.proxy.execute_code(code)
            else:
                print("Not run as proxy is not enabled.")
        except Exception as e:
            print("Error:" + str(e))
    
    def teardown(self):
        """
        Tear down by disable transparent execution
        """
        disable_transparent_execution()
        self.enabled = False